package mx.medinova.api;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,String>> notFound(Exception e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> bad(Exception e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));} @ExceptionHandler(IllegalStateException.class) ResponseEntity<Map<String,String>> conflict(Exception e){return ResponseEntity.status(409).body(Map.of("error",e.getMessage()));} @ExceptionHandler(SecurityException.class) ResponseEntity<Map<String,String>> forbidden(Exception e){return ResponseEntity.status(403).body(Map.of("error",e.getMessage()));} }
